/**
 * Check if a text is a valid date in YYYY-MM-DD format.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  const regex = /^(\d{4})-(\d{2})-(\d{2})$/;
  const match = regex.exec(String(text));
  if (!match) return false;

  const [, year, month, day] = match;
  const date = new Date(text + 'T00:00:00Z');
  if (isNaN(date.getTime())) return false;

  // Validate that the date components match (to catch invalid dates like 2026-02-30)
  if (
    date.getUTCFullYear() !== Number(year) ||
    date.getUTCMonth() + 1 !== Number(month) ||
    date.getUTCDate() !== Number(day)
  ) {
    return false;
  }

  return true;
}

/**
 * Add n days to a date (in UTC).
 * @param {string} date - date in YYYY-MM-DD format
 * @param {number} n - number of days to add
 * @returns {string} - new date in YYYY-MM-DD format
 */
export function addDays(date, n) {
  const d = new Date(date + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  const year = d.getUTCFullYear();
  const month = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/**
 * Calculate the number of days between two dates (b - a, in whole days, UTC).
 * @param {string} a - date in YYYY-MM-DD format
 * @param {string} b - date in YYYY-MM-DD format
 * @returns {number} - number of days (b - a)
 */
export function daysBetween(a, b) {
  const dateA = new Date(a + 'T00:00:00Z');
  const dateB = new Date(b + 'T00:00:00Z');
  const diff = dateB.getTime() - dateA.getTime();
  return Math.floor(diff / (1000 * 60 * 60 * 24));
}

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be in YYYY-MM-DD format.',
  DISCOUNT_INVALID: 'Discount percent must be a number between 0 and 100.',
  LINE_NOT_FOUND: 'No line with that SKU on the invoice.',
  NO_LINES: 'An invoice must have at least one line.',
  NOT_DRAFT: 'Cannot modify an invoice that is not in draft status.',
  NOT_ISSUED: 'Can only record payments on issued or partially paid invoices.',
  OVERPAYMENT: 'Payment amount exceeds the balance due.',
  QTY_INVALID: 'Line quantity must be a positive integer.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

