test('invoiceTotals calculates discount correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 10 * 9500;
  const discount = Math.round((subtotal * 10) / 100);
  const amountAfterDiscount = subtotal - discount;
  const vat = Math.round((amountAfterDiscount * 21) / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

test('invoiceTotals with multiple lines and discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 20 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const line1Total = 10 * 9500;
  const line2Total = 5 * 8500;
  const subtotal = line1Total + line2Total;
  const discount1 = Math.round((line1Total * 10) / 100);
  const discount2 = Math.round((line2Total * 20) / 100);
  const totalDiscount = discount1 + discount2;
  const amount1 = line1Total - discount1;
  const amount2 = line2Total - discount2;
  const vat1 = Math.round((amount1 * 21) / 100);
  const vat2 = Math.round((amount2 * 21) / 100);
  const totalVat = vat1 + vat2;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, totalDiscount);
  assert.equal(totals.vat, totalVat);
  assert.equal(totals.total, subtotal - totalDiscount + totalVat);
});

